function ____exports.mapSummary()
    local s = "七层·衍月塔："
    do
        local i = 0
        while i < #____exports.FLOORS do
            s = s .. ____exports.FLOORS[i + 1]
            if i < #____exports.FLOORS - 1 then
                s = s .. " → "
            end
            i = i + 1
        end
    end
    return s
end
